/**
 * n8n Function node — Format IG data (sheet-ready)
 * Input: items[] (each = Apify dataset item / HTTP->Get Dataset Items)
 * Output columns: Username, FullName, Followers, Following, Posts, Bio, Website, Email, Phone, Verified, Private, Business, ProfileURL, Source
 */

// helpers
function firstNonEmpty(...vals) {
  for (const v of vals) {
    if (v !== undefined && v !== null && String(v).trim() !== "") {
      return String(v).trim();
    }
  }
  return "";
}
function normalizeUrl(u) {
  if (!u) return "";
  try {
    const s = String(u).trim();
    if (s.startsWith("http://") || s.startsWith("https://")) return s;
    return "https://" + s.replace(/^\/+/, "");
  } catch {
    return "";
  }
}
function extractEmail(text) {
  if (!text) return "";
  const m = String(text).match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  return m ? m[0] : "";
}
function extractPhone(text) {
  if (!text) return "";
  const m = String(text).match(/(\+?\d[\d\s().-]{7,}\d)/);
  return m ? m[0].replace(/\s+/g, " ").trim() : "";
}

const out = [];
const seen = new Set();

for (const item of items) {
  const r = item.json || {};

  // core identity
  const username = firstNonEmpty(r.username, r.handle, r.user);
  const fullName = firstNonEmpty(r.fullName, r.name, r.title);

  if (!username) continue; // skip if no handle
  if (seen.has(username)) continue; // de-dupe
  seen.add(username);

  // metrics
  const followers =
    Number(
      r.followersCount ??
      r.followers ??
      r.edge_followed_by?.count ??
      0
    );
  const following =
    Number(
      r.followingCount ??
      r.followsCount ??
      r.edge_follow?.count ??
      0
    );
  const posts =
    Number(
      r.posts ??
      r.mediaCount ??
      r.edge_owner_to_timeline_media?.count ??
      0
    );

  // text + links
  const bio = firstNonEmpty(r.biography, r.bio, r.description);
  // website/external url can live in several keys incl. arrays
  const extArr = Array.isArray(r.externalUrls) ? r.externalUrls : [];
  const extFromArr = extArr.length
    ? firstNonEmpty(extArr[0].url, extArr[0].lynx_url, extArr[0].link, extArr[0].title)
    : "";

  const website = normalizeUrl(
    firstNonEmpty(r.external_url, r.website, r.urlExternal, extFromArr)
  );

  // contact
  const email = firstNonEmpty(
    r.email,
    (Array.isArray(r.emails) && r.emails[0]) || "",
    extractEmail(bio),
    extractEmail(website)
  );
  const phone = firstNonEmpty(r.phone, r.phone_number, extractPhone(bio));

  // flags
  const verified = Boolean(r.isVerified ?? r.is_verified ?? false);
  const isPrivate = Boolean(r.isPrivate ?? r.is_private ?? false);
  const isBusiness = Boolean(r.isBusinessAccount ?? r.is_business_account ?? false);

  // urls
  const profileURL = normalizeUrl(
    firstNonEmpty(
      r.profileUrl,
      r.url,
      `https://www.instagram.com/${username}`
    )
  );
  const source = firstNonEmpty(r.inputUrl, r.source, profileURL);

  out.push({
    json: {
      Username: username,
      FullName: fullName,
      Followers: followers,
      Following: following,
      Posts: posts,
      Bio: bio,
      Website: website,
      Email: email,
      Phone: phone,
      Verified: verified,
      Private: isPrivate,
      Business: isBusiness,
      ProfileURL: profileURL,
      Source: source
    }
  });
}

return out;
